const dishes = [
  { id: 1, name: "Party jollof", price: 3500, category: "Rice", spicy: false, soldOut: false },
  { id: 2, name: "Fried rice", price: 3500, category: "Rice", spicy: false, soldOut: true },
  { id: 3, name: "Ofada rice + ayamase", price: 4800, category: "Rice", spicy: true, soldOut: false },
  { id: 4, name: "Egusi + pounded yam", price: 4500, category: "Soups & swallow", spicy: false, soldOut: false },
  { id: 5, name: "Efo riro + eba", price: 4000, category: "Soups & swallow", spicy: true, soldOut: false },
  { id: 6, name: "Pepper soup", price: 3000, category: "Soups & swallow", spicy: true, soldOut: false },
  { id: 7, name: "Fried plantain", price: 1200, category: "Sides", spicy: false, soldOut: false },
  { id: 8, name: "Moi moi", price: 1000, category: "Sides", spicy: false, soldOut: true },
  { id: 9, name: "Zobo (50cl)", price: 700, category: "Drinks", spicy: false, soldOut: false },
  { id: 10, name: "Chapman", price: 1500, category: "Drinks", spicy: false, soldOut: false },
]
const order = ["Rice", "Soups & swallow", "Sides", "Drinks"]

function DishCard({ dish }) {
  return (
    <article className={dish.soldOut ? "card sold-out" : "card"}>
      <h3>{dish.name}{dish.spicy && " 🌶️"}</h3>
      <p>₦{dish.price.toLocaleString()}</p>
      {dish.soldOut && <span className="badge">Sold out</span>}
    </article>
  )
}

function MenuSection({ title, dishes }) {
  return (
    <section>
      <h2>{title}</h2>
      <div className="grid">
        {dishes.map((d) => <DishCard key={d.id} dish={d} />)}
      </div>
    </section>
  )
}

function App() {
  const soldOut = dishes.filter((d) => d.soldOut).length
  return (
    <main>
      <h1>Mama Put Kitchen · Menu</h1>
      <p className="count">{dishes.length} dishes · {soldOut} sold out</p>
      {order.map((c) => (
        <MenuSection key={c} title={c} dishes={dishes.filter((d) => d.category === c)} />
      ))}
    </main>
  )
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />)
